import{_ as n,a as t,b as r}from"./chunks/ugso_jinja_composed_value.BLVF5-Ng.js";import{_ as i,o as a,c as d,a3 as o}from"./chunks/framework.BlfGB29P.js";const s="/assets/blocks-for-ha/blocks/de/ugso_and.png",l="/assets/blocks-for-ha/blocks/de/ugso_or.png",c="/assets/blocks-for-ha/jinja/de.png",A=JSON.parse('{"title":"Erweiterte HA-Automationen und Jinja","description":"Auslöser, Bedingungen, Ziele, Ablaufgruppen und experimentelle Jinja-Erkennung.","frontmatter":{"title":"Erweiterte HA-Automationen und Jinja","description":"Auslöser, Bedingungen, Ziele, Ablaufgruppen und experimentelle Jinja-Erkennung."},"headers":[],"relativePath":"projects/blocks-for-ha/advanced.md","filePath":"projects/blocks-for-ha/advanced.md","lastUpdated":1793108161000}'),u={name:"projects/blocks-for-ha/advanced.md"};function g(h,e,b,p,m,f){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="erweiterte-ha-automationen-und-jinja" tabindex="-1">Erweiterte HA-Automationen und Jinja <a class="header-anchor" href="#erweiterte-ha-automationen-und-jinja" aria-label="Permalink to &quot;Erweiterte HA-Automationen und Jinja&quot;">​</a></h1><h2 id="ha-optionen-uber-das-zahnrad-seit-0-1-61" tabindex="-1">HA-Optionen über das Zahnrad seit 0.1.61 <a class="header-anchor" href="#ha-optionen-uber-das-zahnrad-seit-0-1-61" aria-label="Permalink to &quot;HA-Optionen über das Zahnrad seit 0.1.61&quot;">​</a></h2><p>Im Zahnrad-Popup eine Option von links in die Liste ziehen. Jede Option ergänzt eine eigene Zeile unter den Pflichtfeldern. Reihenfolge und bewusst ausgewählte leere Zeilen werden im Projekt gespeichert. Entfernen setzt den Wert zurück. Importierte Optionen einschließlich <code>false</code>, <code>0</code>, Listen und Templates erscheinen automatisch und bleiben beim Laden erhalten. Alle Beschriftungen sind in DE/EN/FR verfügbar.</p><p><img src="'+n+'" alt="Kompakter HA-Schritt"></p><table tabindex="0"><thead><tr><th>Geprüfte HA-Blöcke</th><th>Pflichtfelder / Zahnrad-Optionen</th></tr></thead><tbody><tr><td>Alle erweiterten Auslöser und allgemeiner HA-Auslöser</td><td>Typ und Kerneingaben bleiben. Weitere Grenzen, Zustandsfilter, Dauer, Attribute, Templates, Ereignisfilter, Gerätezuordnung, ID, Name, Aktiv und Variablen je nach Auslöser im Zahnrad.</td></tr><tr><td>Erweiterte HA-Bedingung</td><td>Typ und Kerneingaben; optionale Zeitgrenzen, Wochentage, Attribute, Dauer, Name und Aktiv.</td></tr><tr><td>Erweiterter HA-Schritt</td><td>Aktion und Entität; Gerät, Bereich, Etage, Label, Daten, Antwortvariable, Name, Aktiv, Fehlerbehandlung und Metadaten einzeln ergänzbar.</td></tr><tr><td>Zielaktion, allgemeine Aktion, Ereignis senden</td><td>Aktions-/Ereignisname und Ziel bleiben; Daten, Antwortvariable, Listen, Metadaten bzw. Schrittoptionen ergänzbar.</td></tr><tr><td>Warte-Auslöser, Zeitmuster</td><td>Auslöserkette bleibt; Zeitlimit, Verhalten bei Zeitlimit und Schrittoptionen. Zeitfelder einzeln auswählbar; mindestens eines muss für gültiges YAML gesetzt sein.</td></tr><tr><td>Kalender, Temperatur, Integrationsauslöser</td><td>Kerneingaben und erforderliche Schwellenwerte bleiben; weitere Zielarten, Optionen und ID ergänzbar.</td></tr><tr><td>Einfache Auslöser</td><td>ID, mehrere Entitäten/Zustände/Uhrzeiten, jede Änderung, Haltezeit, Sonnenversatz und Ereignisfilter je nach Block.</td></tr><tr><td>Einfache Aktionen/Werte, Variablen</td><td>Kein unnötiges Zahnrad für reine Kerneingaben. Variablennamen und Werte bleiben direkt bearbeitbar.</td></tr><tr><td>Falls, Auswahl, Parallel, Objekte, Listen und Funktionen</td><td>Vorhandene spezialisierte Zahnrad-Editoren bleiben erhalten.</td></tr></tbody></table><p><strong>und</strong>, <strong>oder</strong> und <strong>nicht</strong> sind getrennte Menüblöcke. und/oder haben jeweils einen erweiterbaren Zahnrad-Editor ohne Operatorauswahl; nicht hat einen Eingang. Alte kombinierte Gruppen bleiben lesbar, auch mit mehreren Negationseingängen. YAML-Import verwendet die getrennten Varianten, soweit sie exakt gleichwertig sind.</p><p><img src="'+s+'" alt="und"></p><p><img src="'+l+'" alt="oder"></p><p>Geprüft wurden das Rendern sämtlicher Blockdefinitionen in DE/EN/FR, Projekt-/YAML-Kompatibilität und das Hinzufügen/Entfernen von Optionen. Entitäten, Integrationen und Laufzeitdaten sind weiterhin in HA zu prüfen.</p><p>Seit <strong>0.1.43</strong> bieten die erweiterten HA-Blöcke beschriftete Eingaben statt eines großen JSON-Objekts. Weiterhin 163 Blocktypen: die Kategorien <strong>HA erweitert</strong> und <strong>Jinja (experimentell)</strong> ergänzen die einfachen Blocks. Der Import prüft die unterstützte Struktur; Integration, Geräte-IDs, Templates und Ausführung anschließend in Home Assistant prüfen.</p><p>Alle 15 klassischen erweiterten Auslöser, allgemeine Bedingungen und Schritte sowie Integrationsziele/-optionen, Kalender, Temperaturgrenzen, Zeitmuster, Variablen und Warte-/Schrittoptionen sind umgestellt. <strong>numeric_state</strong> bietet etwa Entität, Über, Unter, Attribut, Template, Dauer und ID. Leere optionale Felder werden nicht ausgegeben; beide Zahlengrenzen sind unabhängig bearbeitbar. Entitätsfelder erlauben HA-Suche, manuelle IDs, JSON-Listen und Templates. Bei Typwechsel in allgemeinen Blöcken zusätzliche Felder gegebenenfalls über die Optionen ergänzen.</p><p>Listen und Objekte als JSON eingeben; <code>null</code> ist ein expliziter Nullwert, <code>&quot;null&quot;</code> der Text. Zustände und Payloads bleiben Text. Unveränderte Werte behalten ihre ursprünglichen Typen und den vollständigen Jinja-Text. <strong>Weitere Optionen (JSON)</strong> erhält zusätzliche Angaben. Komplexe Daten und verschachtelte Zweige bleiben in getrennten JSON-Feldern; sie werden nicht beliebig in anschließbare Zweige zerlegt. Alte JSON-Projekte laden die neuen Felder automatisch; YAML-Import/-Export und gespeicherte Projekte bleiben kompatibel.</p><p><img src="'+t+'" alt="Numeric-state-Auslöser mit einzelnen Eingaben"></p><p>Originalspezifikation: <a href="https://www.home-assistant.io/docs/automation/trigger/" target="_blank" rel="noreferrer">HA-Auslöser</a>, <a href="https://www.home-assistant.io/docs/scripts/conditions/" target="_blank" rel="noreferrer">HA-Bedingungen</a>, <a href="https://www.home-assistant.io/docs/scripts/" target="_blank" rel="noreferrer">HA-Schritte</a>.</p><h2 id="ausloser-und-bedingungen" tabindex="-1">Auslöser und Bedingungen <a class="header-anchor" href="#ausloser-und-bedingungen" aria-label="Permalink to &quot;Auslöser und Bedingungen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bereich</th><th>Unterstützte Ergänzungen</th></tr></thead><tbody><tr><td>Zustand</td><td>Mehrere Entitäten; <code>from</code>, <code>to</code>, <code>not_from</code>, <code>not_to</code>, Listen und <code>null</code>; Attribute und <code>for</code>.</td></tr><tr><td>Zahlen</td><td>Beide Grenzen, Zahlenhelfer als Grenzen, Attribute, <code>value_template</code>, Haltezeit und mehrere Entitäten.</td></tr><tr><td>Zeit</td><td>Uhrzeiten und Listen, Zeithelfer/Sensoren, Zeitquelle mit Offset, Wochentage und Zeitmuster.</td></tr><tr><td>Sonne und HA</td><td>Sonnenauf-/untergang mit Offset; Start und Shutdown.</td></tr><tr><td>Weitere Auslöser</td><td>MQTT, Template, Webhook, Zone, Geräteauslöser, Tag, Sprachbefehl, Geolocation, Ereignis und klassischer Kalender.</td></tr><tr><td>Integrationen</td><td><code>calendar.event_started/ended</code>, <code>temperature.changed</code>, <code>power.changed</code>, <code>motion.detected</code>, <code>timer.finished</code>. Ziele auch über Gerät, Bereich, Etage und Label.</td></tr><tr><td>Bedingungen</td><td>Zeit/Wochentag, Zustand mit Listen/Attribut/Haltezeit/<code>match</code>, Zahlengrenzen, Sonne, Zone, Gerät, Auslöser-ID, Template und verschachtelte UND/ODER/NICHT. Template-Kurzform bleibt erhalten.</td></tr></tbody></table><p>Der Integrationsblock bietet ein Dropdown für Leistung, Bewegung und Timer. Ziel und Optionen werden separat eingegeben. Beim Wechsel werden unveränderte Beispielwerte passend ersetzt; eigene Werte bleiben erhalten. Im erweiterten JSON-Auslöser lassen sich <code>alias</code>, <code>enabled</code>, <code>id</code> und Auslöservariablen angeben. Unbekannte Typen und nicht unterstützte Felder werden mit einer Meldung abgelehnt.</p><h2 id="ziele-variablen-und-optionen" tabindex="-1">Ziele, Variablen und Optionen <a class="header-anchor" href="#ziele-variablen-und-optionen" aria-label="Permalink to &quot;Ziele, Variablen und Optionen&quot;">​</a></h2><p><strong>HA-Aktion mit Zielart</strong> bietet <code>entity_id</code>, <code>device_id</code>, <code>area_id</code>, <code>floor_id</code> und <code>label_id</code>. Eine ID, JSON-Liste oder ein HA-Template ist möglich. Mehrere Zielarten gleichzeitig lassen sich im <strong>HA-Schritt (erweitert)</strong> eingeben. Aktionsdaten dürfen Objekte oder ein vollständiges HA-Template sein; der Import erhält beide Formen.</p><p>Variablen unterstützen zusätzlich Listen und verschachtelte Objekte. Vorhandene Variablen haben einzelne Wertfelder; neue Namen können über die zusätzlichen Optionen ergänzt werden. Gemeinsame Schrittoptionen <code>alias</code>, <code>enabled</code>, <code>continue_on_error</code>, Antwortvariablen und Metadaten haben eigene Eingaben. <code>enabled</code> akzeptiert Boolean oder HA-Template, <code>continue_on_error</code> einen Boolean.</p><p>Unter <strong>Projekt &amp; Beschreibung → HA-Optionen</strong> bearbeiten: <code>variables</code>, <code>trigger_variables</code>, <code>initial_state</code>, <code>trace.stored_traces</code> und <code>max_exceeded</code>. <strong>Anwenden</strong> übernimmt nur gültige Optionen. Nicht mehr enthaltene Optionen werden entfernt; <code>{}</code> entfernt alle Optionen dieses Feldes. Name und Ausführungsmodus bleiben separat. Eine Automation ohne <code>alias</code> kann importiert werden; der Dateiname fällt auf <code>automation.yaml</code> zurück.</p><h2 id="warten-und-ablaufgruppen" tabindex="-1">Warten und Ablaufgruppen <a class="header-anchor" href="#warten-und-ablaufgruppen" aria-label="Permalink to &quot;Warten und Ablaufgruppen&quot;">​</a></h2><ul><li><strong>Warte auf Auslöser</strong> verbindet eine Auslöserkette und bietet <code>timeout</code> / <code>continue_on_timeout</code> im Optionsfeld.</li><li><strong>Aktionsgruppe</strong> erzeugt eine native <code>sequence</code> mit anschließbaren Schritten.</li><li><strong>Parallel</strong> startet native parallele Zweige. Mit dem <strong>Zahnrad</strong> sind 1–100 Zweige möglich. Beim Entfernen eines belegten Zweigs bleibt dessen Inhalt als unverbundener Block erhalten; anschließend verbinden oder löschen.</li><li><strong>Nur weiter wenn</strong> erzeugt eine Bedingung als Aktionsschritt. Ereignis, Assist-Antwort und Szene haben eigene Blocks.</li><li>Wiederholungen unterstützen auch echte Listen/Objekte bei <code>for_each</code>; Pausen erlauben kombinierte Einheiten und Bruchteile. Erweiterte oder gemischte Zweigformen bleiben als JSON-Schritt erhalten.</li></ul><p>Diese Blocks exportieren native HA-Abläufe. Es gibt keine lokale Ausführung und keine parallele JavaScript-Script-Engine.</p><h2 id="jinja-experimentell" tabindex="-1">Jinja (experimentell) <a class="header-anchor" href="#jinja-experimentell" aria-label="Permalink to &quot;Jinja (experimentell)&quot;">​</a></h2><p>Seit <strong>0.1.41</strong> kann <strong>Jinja einlesen</strong> Templates in bearbeitbare, verschachtelte Blocks zerlegen. Template einfügen, die Vorschau prüfen, <strong>Als bearbeitbare Blocks zerlegen</strong> aktiviert lassen und bei Bedarf <strong>Als Bedingung</strong> auswählen. <strong>Block erstellen</strong> legt die zusammenhängende Struktur neben der Automation an. Anschließend den äußeren Wertblock mit einer Variablenzuweisung oder einem Werteingang verbinden; den Bedingungsblock mit einem Boolean-Eingang verbinden. Ohne Zerlegung entsteht ein Originaltextblock.</p><p><img src="'+r+'" alt="Zusammengesetzter Jinja-Wertblock"></p><p>Beispiel: <code>Wasser: {{ states(&#39;sensor.water&#39;) | float(0) | round(1) }} °C</code> wird zu Textteilen und einer Ausgabe mit Entitätsfunktion, <code>float</code>- und <code>round</code>-Block. Das Entitätsfeld öffnet die vorhandene Suche. Entität, Filter, Argumente und Rundungsstellen lassen sich einzeln ändern. Der YAML-Import zerlegt passende Template-Werte, beispielsweise in einer einzelnen Variablenzuweisung, und Template-Bedingungen. Vorhandene spezifischere Blockformen bleiben erhalten. Templates innerhalb von Aktionsdaten-/Options-JSON bleiben im JSON-Feld.</p><p><img src="'+c+'" alt="Bearbeitbare Struktur des Beispiels"></p><table tabindex="0"><thead><tr><th>Unterstützte Teile</th><th>Darstellung</th></tr></thead><tbody><tr><td><code>states</code>, <code>state_attr</code>, <code>is_state</code>, <code>is_state_attr</code> mit fester Entitäts-ID</td><td>Entitätsfunktion mit Suchfeld und Argumentanschlüssen</td></tr><tr><td><code>now()</code>, einfache Variablennamen, Zahlen, Strings in Anführungszeichen, Boolean und <code>none</code></td><td>Ausdrucksblocks; Jinja-Variablennamen sind Textfelder</td></tr><tr><td><code>float</code>, <code>int</code>, <code>round</code>, <code>default</code>, <code>abs</code>, <code>lower</code>, <code>upper</code>, <code>trim</code>, <code>length</code>, <code>string</code>, <code>list</code>, <code>join</code>, <code>replace</code></td><td>Verschachtelte Filter mit 0–3 Positionsargumenten</td></tr><tr><td><code>+</code>, <code>-</code>, <code>*</code>, <code>/</code>, <code>//</code>, <code>%</code>, <code>~</code>, Vergleiche, <code>and</code>, <code>or</code>, <code>not</code></td><td>Berechnungen/Vergleiche mit expliziter Klammerung</td></tr><tr><td><code>wert if bedingung else anderer_wert</code></td><td>Bedingte Wertauswahl</td></tr><tr><td>Text, <code>{{ ... }}</code>, einfache <code>{% if ... %}...{% else %}...{% endif %}</code></td><td>Text-, Ausgabe-, Verbindungs- und Wenn-/Sonst-Blocks</td></tr><tr><td><code>{% for item in items %}...{% else %}...{% endfor %}</code></td><td>Einfache Schleife über einen Ausdruck, optionaler Leerfall und verschachtelte Teile</td></tr></tbody></table><p><strong>Original erhalten:</strong> Unveränderte Strukturen behalten den genauen Originaltext einschließlich Leerraum, auch nach Projekt-Reload und Undo/Redo. Änderungen erzeugen neu formatiertes Jinja. Zurückgesetzte Felder stellen bei gleicher Struktur wieder das Original her. Blockly-Projekte sichern Struktur und Original; YAML sichert den Template-Text, der beim Import wieder analysiert wird.</p><div class="warning custom-block"><p class="custom-block-title">Grenzen der Zerlegung</p><p>Dies ist ein eigener Parser für einen begrenzten Jinja-Umfang. Sobald ein Teil nicht unterstützt wird, bleibt das <strong>gesamte Template</strong> als editierbarer Originalblock erhalten. Dazu gehören etwa <code>set</code>, <code>namespace</code>, Objekt-/Listenzugriffe, Listen-/Objektliterale, Tests wie <code>is defined</code>, Vergleichsketten, <code>elif</code>, benannte Argumente, unbekannte Funktionen/Filter, Kommentare und Whitespace-Steuerzeichen. Keine teilweise Zerlegung, Syntaxgarantie oder lokale Ausführung. Der äußere Wertblock kann ganze Templates enthalten; innerhalb einer anderen Berechnung ist nur eine einzelne Jinja-Ausgabe möglich. Fehlende Anschlüsse oder ungültige Literale verhindern den Export. Grenzen: 10000 Zeichen, 100 Template-Teile und begrenzte Verschachtelung. Jinja-Variablennamen werden nicht automatisch mit anderen Blockly-Variablen umbenannt. Home Assistant übernimmt die Auswertung; dort testen.</p></div><p>Blockly-Projekte sichern auch Blockformen und Anordnung. YAML-Import → Blockly → Export erhält die unterstützten Werte einschließlich ausgelassener Optionalfelder. Grenzen: höchstens 100 Ketteneinträge bzw. Zweige, 10 Ebenen Ablauf-/Bedingungsverschachtelung und begrenzte Daten-/Templategröße. Nicht jede integrationsabhängige Geräteoption wird bereits unterstützt; eine abgelehnte Option wird nicht stillschweigend entfernt.</p><h2 id="originalquellen-und-lizenzhinweise" tabindex="-1">Originalquellen und Lizenzhinweise <a class="header-anchor" href="#originalquellen-und-lizenzhinweise" aria-label="Permalink to &quot;Originalquellen und Lizenzhinweise&quot;">​</a></h2><p>Eigene UGSo-Implementierung auf Basis der öffentlichen Spezifikation, keine kopierte ioBroker-Ausführungsengine. Blockly und Plugin-Lizenzen stehen unter <strong>Über &amp; Lizenzen</strong>; App-Lizenz Apache-2.0.</p><ul><li><a href="https://www.home-assistant.io/docs/automation/trigger/" target="_blank" rel="noreferrer">HA-Auslöser</a>, <a href="https://www.home-assistant.io/docs/scripts/conditions/" target="_blank" rel="noreferrer">Bedingungen</a>, <a href="https://www.home-assistant.io/docs/scripts/" target="_blank" rel="noreferrer">Ablaufbausteine</a> und <a href="https://www.home-assistant.io/docs/automation/yaml/" target="_blank" rel="noreferrer">Automations-YAML</a>.</li><li><a href="https://www.home-assistant.io/triggers/power.changed/" target="_blank" rel="noreferrer">Leistungsänderung</a>, <a href="https://www.home-assistant.io/triggers/motion.detected/" target="_blank" rel="noreferrer">Bewegung</a>, <a href="https://www.home-assistant.io/triggers/timer.finished/" target="_blank" rel="noreferrer">Timer beendet</a>.</li><li><a href="https://jinja.palletsprojects.com/en/stable/templates/" target="_blank" rel="noreferrer">Jinja-Templates</a> und <a href="https://www.home-assistant.io/docs/configuration/templating/" target="_blank" rel="noreferrer">HA-Templates</a>.</li><li><a href="https://docs.blockly.com/guides/create-custom-blocks/overview/" target="_blank" rel="noreferrer">Blockly: eigene Blocks</a> und <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/blocks_for_ha" target="_blank" rel="noreferrer">UGSo-Quellcode</a>.</li></ul>',36)])])}const z=i(u,[["render",g]]);export{A as __pageData,z as default};
